SET @ddl = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='design_requirements' AND column_name='feishu_chat_dissolved_at')=0, 'ALTER TABLE design_requirements ADD COLUMN feishu_chat_dissolved_at DATETIME NULL', 'SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
